  pub const VT_CELL_BEGIN: flatbuffers::VOffsetT = 40;
  pub const VT_CELL_COUNT: flatbuffers::VOffsetT = 42;

  #[inline]
  pub unsafe fn init_from_table(table: flatbuffers::Table<'a>) -> Self {
    Fragment { _tab: table }
  }
  #[allow(unused_mut)]
  pub fn create<'bldr: 'args, 'args: 'mut_bldr, 'mut_bldr, A: flatbuffers::Allocator + 'bldr>(
    _fbb: &'mut_bldr mut flatbuffers::FlatBufferBuilder<'bldr, A>,
    args: &'args FragmentArgs<'args>
  ) -> flatbuffers::WIPOffset<Fragment<'bldr>> {
    let mut builder = FragmentBuilder::new(_fbb);
    builder.add_cell_count(args.cell_count);
    builder.add_cell_begin(args.cell_begin);
    builder.add_component(args.component);
    builder.add_interior_area(args.interior_area);
    builder.add_volume(args.volume);
    builder.add_gltf_node(args.gltf_node);
    builder.add_hull_begin(args.hull_begin);
    if let Some(x) = args.material_fracs { builder.add_material_fracs(x); }
    if let Some(x) = args.material_ids { builder.add_material_ids(x); }
    if let Some(x) = args.inertia { builder.add_inertia(x); }
    if let Some(x) = args.com { builder.add_com(x); }
    builder.add_mass(args.mass);
    builder.add_child_count(args.child_count);
    builder.add_child_begin(args.child_begin);
    builder.add_parent(args.parent);
    builder.add_id(args.id);
    builder.add_hull_count(args.hull_count);
    builder.add_role(args.role);
    builder.add_particle_candidate(args.particle_candidate);
    builder.add_level(args.level);
    builder.finish()
  }


