impl flatbuffers::Verifiable for Fragment<'_> {
  #[inline]
  fn run_verifier(
    v: &mut flatbuffers::Verifier, pos: usize
  ) -> Result<(), flatbuffers::InvalidFlatbuffer> {
    use self::flatbuffers::Verifiable;
    v.visit_table(pos)?
     .visit_field::<u32>("id", Self::VT_ID, false)?
     .visit_field::<u8>("level", Self::VT_LEVEL, false)?
     .visit_field::<i32>("parent", Self::VT_PARENT, false)?
     .visit_field::<u32>("child_begin", Self::VT_CHILD_BEGIN, false)?
     .visit_field::<u32>("child_count", Self::VT_CHILD_COUNT, false)?
     .visit_field::<f32>("mass", Self::VT_MASS, false)?
     .visit_field::<Vec3>("com", Self::VT_COM, false)?
     .visit_field::<Mat3>("inertia", Self::VT_INERTIA, false)?
     .visit_field::<flatbuffers::ForwardsUOffset<flatbuffers::Vector<'_, u16>>>("material_ids", Self::VT_MATERIAL_IDS, false)?
     .visit_field::<flatbuffers::ForwardsUOffset<flatbuffers::Vector<'_, f32>>>("material_fracs", Self::VT_MATERIAL_FRACS, false)?
     .visit_field::<u32>("hull_begin", Self::VT_HULL_BEGIN, false)?
     .visit_field::<u16>("hull_count", Self::VT_HULL_COUNT, false)?
     .visit_field::<bool>("particle_candidate", Self::VT_PARTICLE_CANDIDATE, false)?
     .visit_field::<u8>("role", Self::VT_ROLE, false)?
     .visit_field::<i32>("gltf_node", Self::VT_GLTF_NODE, false)?
     .visit_field::<f32>("volume", Self::VT_VOLUME, false)?
     .visit_field::<f32>("interior_area", Self::VT_INTERIOR_AREA, false)?
     .visit_field::<u32>("component", Self::VT_COMPONENT, false)?
     .visit_field::<u32>("cell_begin", Self::VT_CELL_BEGIN, false)?
     .visit_field::<u32>("cell_count", Self::VT_CELL_COUNT, false)?
     .finish();
    Ok(())
  }
}
