pub struct FragmentBuilder<'a: 'b, 'b, A: flatbuffers::Allocator + 'a> {
  fbb_: &'b mut flatbuffers::FlatBufferBuilder<'a, A>,
  start_: flatbuffers::WIPOffset<flatbuffers::TableUnfinishedWIPOffset>,
}
impl<'a: 'b, 'b, A: flatbuffers::Allocator + 'a> FragmentBuilder<'a, 'b, A> {
  #[inline]
  pub fn add_id(&mut self, id: u32) {
    self.fbb_.push_slot::<u32>(Fragment::VT_ID, id, 0);
  }
  #[inline]
  pub fn add_level(&mut self, level: u8) {
    self.fbb_.push_slot::<u8>(Fragment::VT_LEVEL, level, 0);
  }
  #[inline]
  pub fn add_parent(&mut self, parent: i32) {
    self.fbb_.push_slot::<i32>(Fragment::VT_PARENT, parent, -1);
  }
  #[inline]
  pub fn add_child_begin(&mut self, child_begin: u32) {
    self.fbb_.push_slot::<u32>(Fragment::VT_CHILD_BEGIN, child_begin, 0);
  }
  #[inline]
  pub fn add_child_count(&mut self, child_count: u32) {
    self.fbb_.push_slot::<u32>(Fragment::VT_CHILD_COUNT, child_count, 0);
  }
  #[inline]
  pub fn add_mass(&mut self, mass: f32) {
    self.fbb_.push_slot::<f32>(Fragment::VT_MASS, mass, 0.0);
  }
  #[inline]
  pub fn add_com(&mut self, com: &Vec3) {
    self.fbb_.push_slot_always::<&Vec3>(Fragment::VT_COM, com);
  }
  #[inline]
  pub fn add_inertia(&mut self, inertia: &Mat3) {
    self.fbb_.push_slot_always::<&Mat3>(Fragment::VT_INERTIA, inertia);
  }
  #[inline]
  pub fn add_material_ids(&mut self, material_ids: flatbuffers::WIPOffset<flatbuffers::Vector<'b , u16>>) {
    self.fbb_.push_slot_always::<flatbuffers::WIPOffset<_>>(Fragment::VT_MATERIAL_IDS, material_ids);
  }
  #[inline]
  pub fn add_material_fracs(&mut self, material_fracs: flatbuffers::WIPOffset<flatbuffers::Vector<'b , f32>>) {
    self.fbb_.push_slot_always::<flatbuffers::WIPOffset<_>>(Fragment::VT_MATERIAL_FRACS, material_fracs);
  }
  #[inline]
  pub fn add_hull_begin(&mut self, hull_begin: u32) {
    self.fbb_.push_slot::<u32>(Fragment::VT_HULL_BEGIN, hull_begin, 0);
  }
  #[inline]
  pub fn add_hull_count(&mut self, hull_count: u16) {
    self.fbb_.push_slot::<u16>(Fragment::VT_HULL_COUNT, hull_count, 0);
  }
  #[inline]
  pub fn add_particle_candidate(&mut self, particle_candidate: bool) {
    self.fbb_.push_slot::<bool>(Fragment::VT_PARTICLE_CANDIDATE, particle_candidate, false);
  }
  #[inline]
  pub fn add_role(&mut self, role: u8) {
    self.fbb_.push_slot::<u8>(Fragment::VT_ROLE, role, 0);
  }
  #[inline]
  pub fn add_gltf_node(&mut self, gltf_node: i32) {
    self.fbb_.push_slot::<i32>(Fragment::VT_GLTF_NODE, gltf_node, -1);
  }
  #[inline]
  pub fn add_volume(&mut self, volume: f32) {
    self.fbb_.push_slot::<f32>(Fragment::VT_VOLUME, volume, 0.0);
  }
  #[inline]
  pub fn add_interior_area(&mut self, interior_area: f32) {
    self.fbb_.push_slot::<f32>(Fragment::VT_INTERIOR_AREA, interior_area, 0.0);
  }
  #[inline]
  pub fn add_component(&mut self, component: u32) {
    self.fbb_.push_slot::<u32>(Fragment::VT_COMPONENT, component, 0);
  }
  #[inline]
  pub fn add_cell_begin(&mut self, cell_begin: u32) {
    self.fbb_.push_slot::<u32>(Fragment::VT_CELL_BEGIN, cell_begin, 0);
  }
  #[inline]
  pub fn add_cell_count(&mut self, cell_count: u32) {
    self.fbb_.push_slot::<u32>(Fragment::VT_CELL_COUNT, cell_count, 0);
  }
  #[inline]
  pub fn new(_fbb: &'b mut flatbuffers::FlatBufferBuilder<'a, A>) -> FragmentBuilder<'a, 'b, A> {
    let start = _fbb.start_table();
    FragmentBuilder {
      fbb_: _fbb,
      start_: start,
    }
  }
  #[inline]
  pub fn finish(self) -> flatbuffers::WIPOffset<Fragment<'a>> {
    let o = self.fbb_.end_table(self.start_);
    flatbuffers::WIPOffset::new(o.value())
  }
}

