  #[inline]
  pub unsafe fn init_from_table(table: flatbuffers::Table<'a>) -> Self {
    Bond { _tab: table }
  }
  #[allow(unused_mut)]
  pub fn create<'bldr: 'args, 'args: 'mut_bldr, 'mut_bldr, A: flatbuffers::Allocator + 'bldr>(
    _fbb: &'mut_bldr mut flatbuffers::FlatBufferBuilder<'bldr, A>,
    args: &'args BondArgs<'args>
  ) -> flatbuffers::WIPOffset<Bond<'bldr>> {
    let mut builder = BondBuilder::new(_fbb);
    builder.add_interface_count(args.interface_count);
    builder.add_spawn_count(args.spawn_count);
    builder.add_spawn_begin(args.spawn_begin);
    builder.add_loop_begin(args.loop_begin);
    builder.add_child_count(args.child_count);
    builder.add_child_begin(args.child_begin);
    builder.add_parent_bond(args.parent_bond);
    builder.add_strength_scale(args.strength_scale);
    if let Some(x) = args.rebar_dir { builder.add_rebar_dir(x); }
    builder.add_rebar_area(args.rebar_area);
    if let Some(x) = args.composition { builder.add_composition(x); }
    builder.add_dist_b(args.dist_b);
    builder.add_dist_a(args.dist_a);
    if let Some(x) = args.extent_half { builder.add_extent_half(x); }
    if let Some(x) = args.extent_center { builder.add_extent_center(x); }
    builder.add_j(args.j);
    builder.add_i_uv(args.i_uv);
    builder.add_i_vv(args.i_vv);
    builder.add_i_uu(args.i_uu);
    if let Some(x) = args.frame_v { builder.add_frame_v(x); }
    if let Some(x) = args.frame_u { builder.add_frame_u(x); }
    builder.add_planarity(args.planarity);
    if let Some(x) = args.normal { builder.add_normal(x); }
    if let Some(x) = args.centroid { builder.add_centroid(x); }
    builder.add_area(args.area);
    builder.add_b(args.b);
    builder.add_a(args.a);
    builder.add_id(args.id);
    builder.add_loop_count(args.loop_count);
    builder.add_rebar_count(args.rebar_count);
    builder.add_anchor(args.anchor);
    builder.add_level(args.level);
    builder.finish()
  }


