impl flatbuffers::Verifiable for Bond<'_> {
  #[inline]
  fn run_verifier(
    v: &mut flatbuffers::Verifier, pos: usize
  ) -> Result<(), flatbuffers::InvalidFlatbuffer> {
    use self::flatbuffers::Verifiable;
    v.visit_table(pos)?
     .visit_field::<u32>("id", Self::VT_ID, false)?
     .visit_field::<u8>("level", Self::VT_LEVEL, false)?
     .visit_field::<u32>("a", Self::VT_A, false)?
     .visit_field::<i32>("b", Self::VT_B, false)?
     .visit_field::<f32>("area", Self::VT_AREA, false)?
     .visit_field::<Vec3>("centroid", Self::VT_CENTROID, false)?
     .visit_field::<Vec3>("normal", Self::VT_NORMAL, false)?
     .visit_field::<f32>("planarity", Self::VT_PLANARITY, false)?
     .visit_field::<Vec3>("frame_u", Self::VT_FRAME_U, false)?
     .visit_field::<Vec3>("frame_v", Self::VT_FRAME_V, false)?
     .visit_field::<f32>("i_uu", Self::VT_I_UU, false)?
     .visit_field::<f32>("i_vv", Self::VT_I_VV, false)?
     .visit_field::<f32>("i_uv", Self::VT_I_UV, false)?
     .visit_field::<f32>("j", Self::VT_J, false)?
     .visit_field::<Vec3>("extent_center", Self::VT_EXTENT_CENTER, false)?
     .visit_field::<Vec2>("extent_half", Self::VT_EXTENT_HALF, false)?
     .visit_field::<f32>("dist_a", Self::VT_DIST_A, false)?
     .visit_field::<f32>("dist_b", Self::VT_DIST_B, false)?
     .visit_field::<flatbuffers::ForwardsUOffset<flatbuffers::Vector<'_, flatbuffers::ForwardsUOffset<BondComposition>>>>("composition", Self::VT_COMPOSITION, false)?
     .visit_field::<u16>("rebar_count", Self::VT_REBAR_COUNT, false)?
     .visit_field::<f32>("rebar_area", Self::VT_REBAR_AREA, false)?
     .visit_field::<Vec3>("rebar_dir", Self::VT_REBAR_DIR, false)?
     .visit_field::<f32>("strength_scale", Self::VT_STRENGTH_SCALE, false)?
     .visit_field::<i32>("parent_bond", Self::VT_PARENT_BOND, false)?
     .visit_field::<u32>("child_begin", Self::VT_CHILD_BEGIN, false)?
     .visit_field::<u32>("child_count", Self::VT_CHILD_COUNT, false)?
     .visit_field::<u32>("loop_begin", Self::VT_LOOP_BEGIN, false)?
     .visit_field::<u16>("loop_count", Self::VT_LOOP_COUNT, false)?
     .visit_field::<u32>("spawn_begin", Self::VT_SPAWN_BEGIN, false)?
     .visit_field::<u32>("spawn_count", Self::VT_SPAWN_COUNT, false)?
     .visit_field::<bool>("anchor", Self::VT_ANCHOR, false)?
     .visit_field::<u32>("interface_count", Self::VT_INTERFACE_COUNT, false)?
     .finish();
    Ok(())
  }
}
