pub const ASSET_IDENTIFIER: &str = "FRAC";

#[inline]
pub fn asset_buffer_has_identifier(buf: &[u8]) -> bool {
  flatbuffers::buffer_has_identifier(buf, ASSET_IDENTIFIER, false)
}

#[inline]
pub fn asset_size_prefixed_buffer_has_identifier(buf: &[u8]) -> bool {
  flatbuffers::buffer_has_identifier(buf, ASSET_IDENTIFIER, true)
}

pub const ASSET_EXTENSION: &str = "fracphys";

#[inline]
pub fn finish_asset_buffer<'a, 'b, A: flatbuffers::Allocator + 'a>(
    fbb: &'b mut flatbuffers::FlatBufferBuilder<'a, A>,
    root: flatbuffers::WIPOffset<Asset<'a>>) {
  fbb.finish(root, Some(ASSET_IDENTIFIER));
}

#[inline]
pub fn finish_size_prefixed_asset_buffer<'a, 'b, A: flatbuffers::Allocator + 'a>(fbb: &'b mut flatbuffers::FlatBufferBuilder<'a, A>, root: flatbuffers::WIPOffset<Asset<'a>>) {
  fbb.finish_size_prefixed(root, Some(ASSET_IDENTIFIER));
}
